#include <stdio.h>
#include <string.h>

int main() {
    char words[1000][200];
    int count = 0;
    while (scanf("%s", words[count]) == 1) {
        count++;
    }
    for (int i = count - 1; i >= 0; i--) {
        printf("%s%s", words[i], i > 0 ? " " : "");
    }
    printf("\n");
    return 0;
}
